function planResolution({body,secret,from,transitionId,announcementChannel}){
 if(typeof secret!=='string'||secret.length<24||secret==='YOUR_ACTION_SECRET')throw Error('Configure a strong action secret');if(typeof body?.context?.action_secret!=='string'||body.context.action_secret!==secret)throw Error('Invalid action secret');const incident=body?.context?.pagerduty_incident,channel=body?.channel_id,key=body?.context?.jira_key;if(typeof incident!=='string'||!incident.trim()||typeof channel!=='string'||!channel.trim()||typeof key!=='string'||!/^[A-Za-z][A-Za-z0-9_]*-[1-9][0-9]*$/.test(key))throw Error('Missing or invalid incident, channel or Jira key');if(typeof from!=='string'||!/^\S+@\S+\.\S+$/.test(from))throw Error('Configure PagerDuty user email');if(typeof transitionId!=='string'||!/^\d+$/.test(transitionId))throw Error('Configure Jira transition ID');if(typeof announcementChannel!=='string'||!announcementChannel.trim()||announcementChannel==='YOUR_ANNOUNCEMENT_CHANNEL_ID')throw Error('Configure announcement channel');return{incidentId:incident,channelId:channel,from,announcementChannel,transitionId,endpoint:'/issue/'+encodeURIComponent(key)+'/transitions',jiraBody:{transition:{id:transitionId}}};
}

return {json:planResolution({body:$json.body,secret:$env.MATTERMOST_ACTION_SECRET,from:"YOUR_PAGERDUTY_EMAIL",transitionId:"YOUR_JIRA_TRANSITION_ID",announcementChannel:"YOUR_ANNOUNCEMENT_CHANNEL_ID"})};
